 const biometric=async()=>{if(Platform.OS==='web')return Alert.alert('Unavailable','Fingerprint and face unlock are available in the Android app, not this browser preview.');if(!await LocalAuthentication.hasHardwareAsync()||!await LocalAuthentication.isEnrolledAsync())return Alert.alert('Unavailable','Set up fingerprint or face unlock in phone settings.');let x=await LocalAuthentication.authenticateAsync({promptMessage:'Unlock Dallas'});if(x.success)L(false)};
 const due=()=>{let a=d.recurring.filter(x=>x.nextDate<=today());if(!a.length)return Alert.alert('No items due','No recurring items are due.');Alert.alert('Record recurring items?',a.length+' item(s) will be added.',[{text:'Cancel'},{text:'Record',onPress:()=>{const advance=x=>{let n=new Date((x.nextDate||today())+'T12:00:00');do{if(x.frequency==='daily')n.setDate(n.getDate()+1);else if(x.frequency==='weekly')n.setDate(n.getDate()+7);else if(x.frequency==='yearly')n.setFullYear(n.getFullYear()+1);else n.setMonth(n.getMonth()+1)}while(n.toISOString().slice(0,10)<=today());return {...x,nextDate:n.toISOString().slice(0,10)}};put('transactions',[...a.map(x=>({id:String(Date.now()+Math.random()),type:x.type,amount:x.amount,title:x.title,category:x.category,date:x.nextDate})),...tx]);put('recurring',d.recurring.map(x=>a.some(y=>y.id===x.id)?advance(x):x))}}])};
